StringMap keys = new HashStringMap();
keys.putString("pxObjClass", "Rule-Obj-CaseType");
keys.putString("pyPurpose", "pyDefault");
ParameterPage pp = new ParameterPage();
pp.putString("pyCaseTypePurpose", "CANRESOLVE");
try {
tools.doAction(keys, tools.getPrimaryPage(), pp);
} catch (com.pega.pegarules.pub.generator.RuleNotFoundException ex) {
// No CaseType found: ignore that situation
tools.getStepStatus().backoutWorst();
}

// Start status dependencies i.e. cases that depend on a status of the current work item
pega_processengine_workutilities.pzStartDependencies(myStepPage.getString("pxObjClass"), "Status", false,myStepPage.getString("pyStatusWork"));


// Start complete dependencies i.e cases that depend on the completion of the current work item 
pega_processengine_workutilities.pzStartDependencies(myStepPage.getString("pxObjClass"), "Complete", false);
